            CurriculumVerse(reference: "John 14:2", text: "In my Father’s house are many mansions: if it were not so, I would have told you. I go to prepare a place for you."),
            CurriculumVerse(reference: "1 Thessalonians 4:16-17", text: "For the Lord himself shall descend from heaven with a shout, with the voice of the archangel, and with the trump of God: and the dead in Christ shall rise first: Then we which are alive and remain shall be caught up together with them in the clouds, to meet the Lord in the air: and so shall we ever be with the Lord."),
            CurriculumVerse(reference: "Revelation 21:4", text: "And God shall wipe away all tears from their eyes; and there shall be no more death, neither sorrow, nor crying, neither shall there be any more pain: for the former things are passed away."),
            CurriculumVerse(reference: "John 11:25", text: "Jesus said unto her, I am the resurrection, and the life: he that believeth in me, though he were dead, yet shall he live:"),
            CurriculumVerse(reference: "2 Corinthians 4:17", text: "For our light affliction, which is but for a moment, worketh for us a far more exceeding and eternal weight of glory;"),
            CurriculumVerse(reference: "1 Corinthians 15:52", text: "In a moment, in the twinkling of an eye, at the last trump: for the trumpet shall sound, and the dead shall be raised incorruptible, and we shall be changed."),
            CurriculumVerse(reference: "Philippians 3:20", text: "For our conversation is in heaven; from whence also we look for the Saviour, the Lord Jesus Christ:"),
            CurriculumVerse(reference: "Titus 2:13", text: "Looking for that blessed hope, and the glorious appearing of the great God and our Saviour Jesus Christ;"),
            CurriculumVerse(reference: "Revelation 22:12", text: "And, behold, I come quickly; and my reward is with me, to give every man according as his work shall be."),
            CurriculumVerse(reference: "1 John 5:13", text: "These things have I written unto you that believe on the name of the Son of God; that ye may know that ye have eternal life, and that ye may believe on the name of the Son of God."),
        ]),
    ]

    /// All curriculum verses in journey order.
    static var allVerses: [CurriculumVerse] { units.flatMap { $0.verses } }

    /// Bundled KJV text for a reference, if it is part of the curriculum.
    static func text(for reference: String) -> String? {
        allVerses.first { $0.reference == reference }?.text
    }

    /// The unit that contains a given reference.
    static func unit(for reference: String) -> CurriculumUnit? {
        units.first { $0.verses.contains { $0.reference == reference } }
    }
}
